+// API keys and audit log. Every request that changes data writes an audit
+// entry; GET /audit lists them newest first.
+
+/** Finds an API key entry by its secret key, or null. */
+export function findApiKey(store, key) {
+  if (!key) return null;
+  return (store.data.apiKeys ?? []).find((entry) => entry.key === key) ?? null;
+}
+
+/** Appends an audit entry for a data-changing request and returns it. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.at.localeCompare(a.at) || b.id - a.id);
+}
