diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..94ebcfe
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,153 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { mkdtempSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { openStore } from "../src/db/store.js";
+import { createApp } from "../src/http/server.js";
+import { CODES } from "../src/errors.js";
+import { LANGUAGES, t } from "../src/i18n/messages.js";
+import { app, auth, NOW, seed } from "./helpers.js";
+
+test("missing or unknown key is 401 with unauthorized error", async () => {
+  const { handle } = app();
+  for (const headers of [
+    {},
+    { authorization: "" },
+    { authorization: "Basic larder-manager-key" },
+    { authorization: "Bearer " },
+    { authorization: "Bearer nope" },
+  ]) {
+    const res = await handle({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.ok(res.body.error.message.length > 0);
+  }
+  const unknownRoute = await handle({ path: "/nope" });
+  assert.equal(unknownRoute.status, 401);
+  assert.equal(unknownRoute.body.error.code, "unauthorized");
+});
+
+test("Authorization header lookup is case-insensitive", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { Authorization: "Bearer larder-viewer-key" } });
+  assert.equal(res.status, 200);
+});
+
+test("viewer can read GET routes except /audit and cannot change data", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ path: "/items", headers: auth("viewer") })).status, 200);
+  assert.equal((await handle({ path: "/alerts", headers: auth("viewer") })).status, 200);
+
+  for (const req of [
+    { method: "GET", path: "/audit" },
+    { method: "POST", path: "/recipes/1/cook", body: { portions: 4 } },
+    { method: "POST", path: "/batches/1/waste", body: { qty: 1 } },
+    { method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: [] } },
+  ]) {
+    const res = await handle({ ...req, headers: auth("viewer") });
+    assert.equal(res.status, 403, `${req.method} ${req.path}`);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("cook can read, cook, waste, log temperatures and enter stock-take counts", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ path: "/items", headers: auth("cook") })).status, 200);
+
+  const cooked = await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("cook"), body: { portions: 4 } });
+  assert.equal(cooked.status, 200);
+
+  const wasted = await handle({ method: "POST", path: "/batches/6/waste", headers: auth("cook"), body: { qty: 0.5, reason: "spill" } });
+  assert.equal(wasted.status, 201);
+
+  const temp = await handle({ method: "POST", path: "/temperatures", headers: auth("cook"), body: { location: "fridge", celsius: 4 } });
+  assert.equal(temp.status, 201);
+
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: auth("manager"), body: { location: "dry" } })).body;
+  const counted = await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: auth("cook"), body: { batchId: 6, counted: 12 } });
+  assert.equal(counted.status, 200);
+
+  for (const req of [
+    { method: "GET", path: "/audit" },
+    { method: "POST", path: "/stocktakes", body: { location: "fridge" } },
+    { method: "POST", path: `/stocktakes/${take.id}/finish` },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } },
+    { method: "POST", path: "/orders/3/send" },
+    { method: "POST", path: "/orders/3/cancel" },
+    { method: "POST", path: "/orders/2/receive", body: { lots: [] } },
+    { method: "POST", path: "/prices", body: { supplierId: 1, itemId: 1, priceCents: 100, validFrom: "2026-10-28" } },
+    { method: "POST", path: "/dishes", body: { name: "Test", recipeId: 1, priceCents: 500 } },
+    { method: "POST", path: "/jobs/nightly" },
+    { method: "POST", path: "/import/items", body: { csv: "" } },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: [] } },
+  ]) {
+    const res = await handle({ ...req, headers: auth("cook") });
+    assert.equal(res.status, 403, `${req.method} ${req.path}`);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("audit records data changes and GET /audit lists them newest first for managers", async () => {
+  let tick = NOW;
+  const { store } = app();
+  const handle = createApp(store, { clock: () => tick });
+
+  await handle({ path: "/items", headers: auth("viewer") });
+  await handle({ method: "POST", path: "/recipes/2/cook", headers: auth("cook"), body: { portions: 100 } });
+  await handle({ method: "POST", path: "/orders", headers: auth("cook"), body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } });
+
+  assert.equal((await handle({ path: "/audit", headers: auth("manager") })).body.length, 0);
+
+  await handle({ method: "POST", path: "/temperatures", headers: auth("cook"), body: { location: "fridge", celsius: 3 } });
+  tick += 5000;
+  await handle({ method: "POST", path: "/orders", headers: auth("manager"), body: { supplierId: 1, lines: [{ itemId: 1, qty: 2 }] } });
+
+  const auditRes = await handle({ path: "/audit", headers: auth("manager") });
+  assert.equal(auditRes.status, 200);
+  assert.equal(auditRes.body.length, 2);
+  assert.deepEqual(auditRes.body[0], {
+    id: 2,
+    at: new Date(NOW + 5000).toISOString(),
+    keyName: "manager",
+    method: "POST",
+    path: "/orders",
+    status: 201,
+  });
+  assert.deepEqual(auditRes.body[1], {
+    id: 1,
+    at: new Date(NOW).toISOString(),
+    keyName: "cook",
+    method: "POST",
+    path: "/temperatures",
+    status: 201,
+  });
+});
+
+test("audit entries are saved to disk on file-backed stores", async () => {
+  const dir = mkdtempSync(join(tmpdir(), "larder-auth-"));
+  const file = join(dir, "db.json");
+  writeFileSync(file, JSON.stringify(seed(), null, 2));
+  const handle = createApp(openStore(file), { clock: () => NOW });
+
+  const res = await handle({ method: "POST", path: "/batches/1/waste", headers: auth("cook"), body: { qty: 1, reason: "spoiled" } });
+  assert.equal(res.status, 201);
+
+  const reopened = createApp(openStore(file), { clock: () => NOW });
+  const auditRes = await reopened({ path: "/audit", headers: auth("manager") });
+  assert.equal(auditRes.status, 200);
+  assert.equal(auditRes.body.length, 1);
+  assert.equal(auditRes.body[0].keyName, "cook");
+  assert.equal(auditRes.body[0].path, "/batches/1/waste");
+});
+
+test("every error code has messages in every language", () => {
+  for (const lang of LANGUAGES) {
+    for (const code of Object.keys(CODES)) {
+      const msg = t(code, lang, { id: 1, reason: "x", item: "onion", available: 1, unit: "kg", state: "draft", action: "received" });
+      assert.notEqual(msg, code, `${lang}:${code} missing message`);
+    }
+  }
+});
